-- STELLUN Academy content: books, pictures, and terminology.
-- Run this whole file once in the Supabase SQL editor (project: Stellun).
-- Safe to run again: tables use IF NOT EXISTS and rows use ON CONFLICT.
-- Access: anyone can read these tables (public study content). Only the
-- project owner can change them, through the dashboard or this SQL editor.

create table if not exists public.academy_books (
  id text primary key,
  title text not null,
  authors text not null default '',
  isbn13 text not null,
  topic text not null,
  note text not null default '',
  free_url text,
  free_label text,
  cover_url text,
  created_at timestamptz not null default now()
);

create table if not exists public.academy_pictures (
  slug text primary key,
  title text not null,
  url text not null,
  credit text not null default '',
  tags text[] not null default '{}',
  track text not null default 'stem',
  created_at timestamptz not null default now()
);

create table if not exists public.academy_terms (
  id text primary key,
  term text not null,
  track text not null,
  category text not null,
  short text not null,
  detail text not null,
  symbol text,
  units text,
  aka text[] not null default '{}'
);

alter table public.academy_books enable row level security;
alter table public.academy_pictures enable row level security;
alter table public.academy_terms enable row level security;

drop policy if exists "academy_books are readable" on public.academy_books;
create policy "academy_books are readable" on public.academy_books for select to anon, authenticated using (true);
drop policy if exists "academy_pictures are readable" on public.academy_pictures;
create policy "academy_pictures are readable" on public.academy_pictures for select to anon, authenticated using (true);
drop policy if exists "academy_terms are readable" on public.academy_terms;
create policy "academy_terms are readable" on public.academy_terms for select to anon, authenticated using (true);

-- Books (cover_url is the Open Library cover for the ISBN; replace it with any cover link you prefer).

-- Pictures (NASA public-domain images, linked from the NASA-3D-Resources collection).

-- Terminology (four sections: aviation, astronomy, aerospace, stem).
