insert into public.academy_pictures (slug, title, url, credit, tags, track) values ('bp-tauri', 'BP Tauri', 'https://raw.githubusercontent.com/nasa/NASA-3D-Resources/master/3D%20Models/BP%20Tauri/BP%20Tauri.png', 'NASA, via the NASA-3D-Resources collection (public domain)', ARRAY['tauri']::text[], 'stem') on conflict (slug) do update set title = excluded.title, url = excluded.url, credit = excluded.credit, tags = excluded.tags, track = excluded.track;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('low-earth-orbit', 'Low Earth Orbit', 'aerospace', 'orbits', 'Roughly 160 to 2,000 km altitude, orbital period near 90 minutes.', 'The band that holds the International Space Station, most Earth observation satellites, and the large communications constellations. Orbital speed is about 7.8 km/s near 400 km, so a revolution takes roughly 90 minutes. Residual atmosphere still produces measurable drag, so satellites here need periodic reboosts or they re-enter.', NULL, NULL, ARRAY['LEO']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('medium-earth-orbit', 'Medium Earth Orbit', 'aerospace', 'orbits', 'Between LEO and geostationary altitude, about 2,000 to 35,786 km.', 'Home to the navigation constellations. GPS flies near 20,200 km with a period close to 11 hours 58 minutes, Galileo near 23,200 km, GLONASS near 19,100 km. Higher altitude means fewer satellites are needed for global coverage, at the cost of a longer signal path and passage through the inner radiation belt.', NULL, NULL, ARRAY['MEO']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('geostationary-orbit', 'Geostationary Orbit', 'aerospace', 'orbits', 'Circular equatorial orbit at 35,786 km where the period matches Earth''s rotation.', 'A satellite in a circular orbit at 35,786 km over the equator has a period of one sidereal day, so it appears fixed above one longitude. Used for broadcast, fixed communications, and weather imagers that need a constant hemispheric view. Station keeping corrects for lunar and solar perturbations and the equatorial bulge.', NULL, NULL, ARRAY['GEO']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('geosynchronous-orbit', 'Geosynchronous Orbit', 'aerospace', 'orbits', 'One-sidereal-day period, but not necessarily equatorial or circular.', 'Any orbit whose period equals Earth''s rotation period. If it is inclined or eccentric, the ground track traces a figure eight or an analemma instead of holding a fixed point. Geostationary orbit is the special zero-inclination, zero-eccentricity case.', NULL, NULL, ARRAY['GSO']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('sun-synchronous-orbit', 'Sun-Synchronous Orbit', 'aerospace', 'orbits', 'Near-polar orbit whose plane precesses once per year, fixing the local solar time.', 'Inclination is chosen (typically 96 to 100 degrees at 600 to 800 km) so that Earth''s oblateness drags the orbital plane eastwards about 0.9856 degrees per day, matching Earth''s motion around the Sun. Every pass over a given latitude then happens at the same local solar time, giving consistent illumination for imaging.', NULL, NULL, ARRAY['SSO']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('polar-orbit', 'Polar Orbit', 'aerospace', 'orbits', 'High-inclination orbit passing near both poles.', 'Inclination near 90 degrees, so the ground track eventually covers the entire surface as Earth turns beneath it. Standard for reconnaissance, meteorology, and global environmental monitoring.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('molniya-orbit', 'Molniya Orbit', 'aerospace', 'orbits', 'Highly eccentric 12-hour orbit with apogee over high northern latitudes.', 'Inclination near 63.4 degrees, which freezes the argument of perigee so apogee stays over the same hemisphere. The spacecraft loiters near apogee for hours, giving long high-latitude coverage that geostationary satellites cannot provide.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('tundra-orbit', 'Tundra Orbit', 'aerospace', 'orbits', 'Eccentric 24-hour orbit with a long dwell over one region.', 'A geosynchronous-period orbit with significant eccentricity and inclination. The ground track is a closed loop, so one satellite dwells over a chosen service area for most of the day.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('graveyard-orbit', 'Graveyard Orbit', 'aerospace', 'orbits', 'Storage orbit above GEO for retired geostationary satellites.', 'Inter-Agency Space Debris Coordination Committee guidelines call for raising a retired geostationary satellite a few hundred kilometres above the operational belt and passivating it, so it cannot drift back through the crowded ring.', NULL, NULL, ARRAY['Disposal orbit']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('highly-elliptical-orbit', 'Highly Elliptical Orbit', 'aerospace', 'orbits', 'Large eccentricity orbit with a low perigee and a far apogee.', 'Used by magnetospheric and X-ray astronomy missions that need to spend most of their time outside the radiation belts, and by communications systems needing high-latitude dwell.', NULL, NULL, ARRAY['HEO']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('halo-orbit', 'Halo Orbit', 'aerospace', 'orbits', 'Quasi-periodic orbit around a collinear Lagrange point.', 'A three-dimensional path around L1 or L2 that never passes directly behind the secondary body, which keeps the spacecraft in sunlight and in view of the ground. The James Webb Space Telescope flies a halo orbit around Sun-Earth L2.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('lagrange-point', 'Lagrange Point', 'aerospace', 'orbits', 'Five equilibrium points in a two-body gravitational system.', 'Positions where the gravity of two large bodies and the centrifugal effect of their rotation balance for a small third body. L1, L2, and L3 are collinear and unstable, requiring small station keeping burns. L4 and L5 form equilateral triangles with the two bodies and are stable.', NULL, NULL, ARRAY['Libration point','L1 to L5']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('near-rectilinear-halo-orbit', 'Near-Rectilinear Halo Orbit', 'aerospace', 'orbits', 'Elongated lunar halo orbit with favourable access and communications.', 'A high-eccentricity halo orbit about the Earth-Moon L2 region, planned for the Gateway station. It offers near-continuous Earth communications, modest station keeping cost, and low delta-v transfers to lunar orbit.', NULL, NULL, ARRAY['NRHO']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('heliocentric-orbit', 'Heliocentric Orbit', 'aerospace', 'orbits', 'An orbit around the Sun rather than a planet.', 'Interplanetary spacecraft spend most of their cruise in heliocentric orbit. Trajectory design is expressed in heliocentric elements, with planetary encounters treated as brief patched-conic segments.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('retrograde-orbit', 'Retrograde Orbit', 'aerospace', 'orbits', 'Orbit with inclination above 90 degrees, moving against the primary''s rotation.', 'Launching retrograde is expensive from Earth because the launch site''s rotational velocity works against the vehicle. Retrograde orbits appear mostly around other bodies or in specialised remote sensing cases.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('frozen-orbit', 'Frozen Orbit', 'aerospace', 'orbits', 'Orbit tuned so eccentricity and argument of perigee stay nearly constant.', 'By choosing a small eccentricity and an argument of perigee near 90 degrees, the secular effects of Earth''s gravity field cancel, holding altitude over a target latitude steady and reducing station keeping.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('repeat-ground-track-orbit', 'Repeat Ground Track Orbit', 'aerospace', 'orbits', 'Orbit whose ground track exactly repeats after a fixed number of revolutions.', 'Altitude is chosen so that an integer number of revolutions matches an integer number of nodal days. Essential for interferometric and change-detection missions that must revisit the same geometry.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('orbital-decay', 'Orbital Decay', 'aerospace', 'orbits', 'Progressive loss of altitude from drag and other dissipative effects.', 'In LEO, atmospheric drag removes energy, shrinking the orbit and speeding decay as density rises. Decay rate depends on area-to-mass ratio and on solar activity, which expands the thermosphere near solar maximum.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('orbital-period', 'Orbital Period', 'aerospace', 'orbits', 'Time for one complete revolution.', 'For a two-body orbit, T equals 2 pi times the square root of a cubed over mu, where a is the semi-major axis and mu is the gravitational parameter of the primary. Period depends only on semi-major axis, not on eccentricity.', 'T', 'minutes or hours', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('ground-track', 'Ground Track', 'aerospace', 'orbits', 'The path the sub-satellite point traces on the surface.', 'The projection of the orbit onto the rotating body. Successive tracks shift west by the amount the body rotates during one revolution, about 22.5 degrees of longitude for a 90-minute LEO orbit.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('semi-major-axis', 'Semi-Major Axis', 'aerospace', 'keplerian', 'Half the long axis of the orbital ellipse; sets the period and energy.', 'The single element that determines orbital period and specific orbital energy. For a circular orbit it equals the orbital radius. Raising a is the definition of raising an orbit.', 'a', 'km', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('eccentricity', 'Eccentricity', 'aerospace', 'keplerian', 'Shape of the orbit, from 0 for a circle to below 1 for an ellipse.', 'Zero is circular, values between 0 and 1 are elliptical, exactly 1 is parabolic (escape), and above 1 is hyperbolic. Perigee radius equals a times (1 minus e); apogee radius equals a times (1 plus e).', 'e', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('inclination', 'Inclination', 'aerospace', 'keplerian', 'Tilt of the orbital plane relative to the reference equator.', 'Zero degrees is equatorial and prograde, 90 degrees is polar, and above 90 degrees is retrograde. The minimum inclination reachable directly from a launch site equals that site''s latitude.', 'i', 'degrees', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('right-ascension-of-the-ascending-node', 'Right Ascension of the Ascending Node', 'aerospace', 'keplerian', 'Where the orbit plane crosses the equator going north, measured along the equator.', 'Measured eastwards from the vernal equinox direction to the ascending node. Earth''s oblateness makes RAAN drift, which is exploited in sun-synchronous design and must be accounted for when phasing a constellation.', 'RAAN', 'degrees', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('argument-of-perigee', 'Argument of Perigee', 'aerospace', 'keplerian', 'Angle from the ascending node to perigee, measured in the orbital plane.', 'Sets where in the orbit the spacecraft is closest to the primary. It also precesses under the oblateness perturbation, except near the critical inclination of about 63.4 degrees where the drift vanishes.', 'omega', 'degrees', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('true-anomaly', 'True Anomaly', 'aerospace', 'keplerian', 'Angular position of the spacecraft along its orbit, measured from perigee.', 'The instantaneous position angle at the focus. Together with the other five elements and an epoch, it fully specifies the state.', 'nu', 'degrees', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('mean-anomaly', 'Mean Anomaly', 'aerospace', 'keplerian', 'Position angle a fictitious body would have moving at constant angular rate.', 'Advances linearly with time, which is why it is the element published in two-line element sets. Converting to true anomaly requires solving Kepler''s equation for the eccentric anomaly.', 'M', 'degrees', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('eccentric-anomaly', 'Eccentric Anomaly', 'aerospace', 'keplerian', 'Intermediate angle linking mean anomaly to true anomaly.', 'Defined on the circumscribing circle of the ellipse. Kepler''s equation, M equals E minus e times sin E, is solved iteratively for E, then converted to true anomaly.', 'E', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('kepler-s-equation', 'Kepler''s Equation', 'aerospace', 'keplerian', 'The transcendental relation between mean and eccentric anomaly.', 'M equals E minus e sin E. It has no closed-form solution for E, so propagators use Newton-Raphson or series methods. This is the core of every analytic two-body propagator.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('epoch', 'Epoch', 'aerospace', 'keplerian', 'The instant at which a set of orbital elements is valid.', 'Elements degrade with time because of perturbations, so element sets are timestamped. Propagating far from epoch increases position error, which is why operational tracking uses freshly published sets.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('two-line-element-set', 'Two-Line Element Set', 'aerospace', 'keplerian', 'Compact fixed-format description of a satellite orbit at an epoch.', 'Encodes inclination, right ascension of the ascending node, eccentricity, argument of perigee, mean anomaly, mean motion, and a drag term. It is defined for use with the SGP4 model, and mixing it with a plain two-body propagator introduces error.', NULL, NULL, ARRAY['TLE']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('orbit-mean-elements-message', 'Orbit Mean-Elements Message', 'aerospace', 'keplerian', 'Modern standardised replacement format for element sets.', 'A Consultative Committee for Space Data Systems format carrying the same mean elements as a two-line set in a self-describing structure, with no column limits on names or catalogue numbers.', NULL, NULL, ARRAY['OMM']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('mean-motion', 'Mean Motion', 'aerospace', 'keplerian', 'Average angular rate around the orbit.', 'Directly related to semi-major axis. Element sets publish mean motion instead of altitude, so altitude figures on tracking displays are derived quantities.', 'n', 'revolutions per day', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('sgp4', 'SGP4', 'aerospace', 'keplerian', 'Standard analytic propagator paired with two-line element sets.', 'Simplified General Perturbations model 4 includes secular and periodic effects of Earth''s oblateness, atmospheric drag, and lunar and solar gravity in an approximate form. Typical accuracy is kilometres near epoch, degrading over days.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('j2-perturbation', 'J2 Perturbation', 'aerospace', 'keplerian', 'Dominant effect of Earth''s equatorial bulge on an orbit.', 'The second zonal harmonic of the gravity field causes secular drift in right ascension of the ascending node and argument of perigee. It is the largest non-spherical gravity term and the basis of sun-synchronous and frozen orbit design.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('perigee-and-apogee', 'Perigee and Apogee', 'aerospace', 'keplerian', 'Closest and farthest points of an Earth orbit.', 'The general terms are periapsis and apoapsis; around the Sun they are perihelion and aphelion, and around the Moon perilune and apolune. Speed is highest at periapsis and lowest at apoapsis.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('state-vector', 'State Vector', 'aerospace', 'keplerian', 'Position and velocity at an epoch, in a stated reference frame.', 'Six numbers equivalent to the Keplerian elements. Numerical propagators integrate state vectors directly, which handles perturbations that analytic element methods approximate.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('specific-orbital-energy', 'Specific Orbital Energy', 'aerospace', 'keplerian', 'Orbital energy per unit mass; negative for bound orbits.', 'Equal to minus mu divided by twice the semi-major axis. The vis-viva equation relates it to speed and radius, and it is the quantity a burn changes when raising or lowering an orbit.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('vis-viva-equation', 'Vis-Viva Equation', 'aerospace', 'keplerian', 'Relates orbital speed to radius and semi-major axis.', 'v squared equals mu times (2 over r minus 1 over a). It gives the speed at any point of an orbit and underlies every impulsive transfer calculation.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('sphere-of-influence', 'Sphere of Influence', 'aerospace', 'keplerian', 'Region where one body''s gravity dominates trajectory design.', 'Used in the patched-conic method: inside the sphere the trajectory is treated as a two-body problem about that body, and outside it about the Sun. An approximation, but accurate enough for preliminary interplanetary design.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('ground-elevation-angle', 'Ground Elevation Angle', 'aerospace', 'keplerian', 'Angle of a spacecraft above the local horizon as seen from a site.', 'Pass planning uses a minimum usable elevation, often 5 to 10 degrees, because atmospheric path length and terrain blockage degrade the link at low elevation.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('delta-v', 'Delta-v', 'aerospace', 'maneuvers', 'Change in velocity a maneuver requires; the currency of mission design.', 'Every orbital change is priced in delta-v, and delta-v is converted into propellant through the rocket equation. Reaching LEO costs roughly 9.3 to 10 km/s including losses; LEO to geostationary transfer plus circularisation costs roughly 3.9 to 4.3 km/s.', 'dv', 'km/s or m/s', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('delta-v-budget', 'Delta-v Budget', 'aerospace', 'maneuvers', 'Itemised allocation of velocity change for a whole mission.', 'Lists ascent, transfers, plane changes, rendezvous, station keeping over the design life, attitude control leakage, and disposal, plus margin. It sizes the propulsion system and often decides the launch vehicle.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('tsiolkovsky-rocket-equation', 'Tsiolkovsky Rocket Equation', 'aerospace', 'maneuvers', 'Links delta-v to exhaust velocity and mass ratio.', 'dv equals the effective exhaust velocity times the natural logarithm of initial mass over final mass. Because the relation is logarithmic, each increment of delta-v costs exponentially more propellant.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('hohmann-transfer', 'Hohmann Transfer', 'aerospace', 'maneuvers', 'Two-burn minimum-energy transfer between coplanar circular orbits.', 'The first burn raises apoapsis to the target radius, the second circularises there. It is the cheapest two-impulse transfer for moderate radius ratios but also the slowest, so mission design trades it against time of flight.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('bi-elliptic-transfer', 'Bi-Elliptic Transfer', 'aerospace', 'maneuvers', 'Three-burn transfer that beats a Hohmann transfer at large radius ratios.', 'Uses a very high intermediate apoapsis so the plane change and circularisation happen where velocity is low. It costs less delta-v than a Hohmann transfer when the final radius exceeds about 11.94 times the initial radius, at the cost of much longer flight time.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('plane-change-maneuver', 'Plane Change Maneuver', 'aerospace', 'maneuvers', 'Rotating the orbital plane, priced by orbital speed at the burn point.', 'Cost is 2 v sin(half the angle), so plane changes are performed as high and slow as possible, ideally combined with a circularisation burn. Large inclination changes in LEO are prohibitively expensive.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('combined-maneuver', 'Combined Maneuver', 'aerospace', 'maneuvers', 'Single burn that changes speed and direction at once.', 'Vector-adding a plane change into an apogee circularisation burn costs less than performing the two separately, which is standard practice for geostationary insertion from an inclined transfer orbit.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('geostationary-transfer-orbit', 'Geostationary Transfer Orbit', 'aerospace', 'maneuvers', 'Elliptical staging orbit with apogee near geostationary altitude.', 'Launchers deliver payloads to a transfer orbit with perigee in LEO and apogee near 35,786 km. The satellite then performs its own apogee burn to circularise and remove inclination.', NULL, NULL, ARRAY['GTO']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('apogee-kick', 'Apogee Kick', 'aerospace', 'maneuvers', 'Burn at apogee that circularises a transfer orbit.', 'Performed by an integral engine or a dedicated apogee motor. Because it occurs at the slowest point of the orbit, it is the efficient place to combine circularisation with the inclination change.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('oberth-effect', 'Oberth Effect', 'aerospace', 'maneuvers', 'A burn deep in a gravity well delivers more energy change.', 'Kinetic energy scales with velocity squared, so the same delta-v applied where the spacecraft is moving fastest, at periapsis, produces a larger change in orbital energy. Escape burns are therefore performed at low periapsis.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('gravity-assist', 'Gravity Assist', 'aerospace', 'maneuvers', 'Using a planetary encounter to change heliocentric velocity for free.', 'The flyby is a rotation of velocity in the planet''s frame, but in the Sun''s frame it exchanges momentum with the planet, changing speed and direction. Voyager, Cassini, Parker Solar Probe, and Europa Clipper all depend on assist sequences.', NULL, NULL, ARRAY['Flyby','Swing-by']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('aerobraking', 'Aerobraking', 'aerospace', 'maneuvers', 'Using repeated shallow atmospheric passes to shrink an orbit.', 'Mars orbiters have used dozens to hundreds of drag passes to lower apoapsis, saving substantial propellant at the cost of months of operations and careful thermal and dynamic pressure limits.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('aerocapture', 'Aerocapture', 'aerospace', 'maneuvers', 'Single atmospheric pass that converts a hyperbolic arrival into orbit.', 'A one-pass, high-heating alternative to propulsive capture. Studied extensively and demonstrated in analogous entry guidance, but not yet flown as a primary capture method on a planetary mission.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('station-keeping', 'Station Keeping', 'aerospace', 'maneuvers', 'Small routine burns that hold an operational orbit inside its box.', 'Geostationary satellites correct north-south drift from lunar and solar gravity and east-west drift from the equatorial bulge, typically spending 45 to 55 m/s per year. LEO spacecraft reboost against drag instead.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('phasing-maneuver', 'Phasing Maneuver', 'aerospace', 'maneuvers', 'Changing arrival timing by temporarily changing period.', 'Raising or lowering the orbit changes the period, letting a chaser catch up with or fall back towards a target. Constellation deployment uses long low-thrust phasing to spread satellites across a plane.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('rendezvous-and-docking', 'Rendezvous and Docking', 'aerospace', 'maneuvers', 'Bringing two spacecraft to the same state and mating them.', 'Proceeds through phasing, far-field approach, proximity operations along a defined corridor, then capture. Cargo and crew vehicles at the International Space Station follow approach ellipsoid and keep-out sphere rules enforced by flight rules.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('clohessy-wiltshire-equations', 'Clohessy-Wiltshire Equations', 'aerospace', 'maneuvers', 'Linearised relative motion model used for proximity operations.', 'Describe a chaser''s motion in a rotating frame centred on the target for near-circular orbits. They explain counter-intuitive behaviour such as thrusting forward causing the chaser to rise and fall behind.', NULL, NULL, ARRAY['Hill''s equations']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('collision-avoidance-maneuver', 'Collision Avoidance Maneuver', 'aerospace', 'maneuvers', 'Burn to raise the miss distance for a predicted close approach.', 'Triggered when a conjunction assessment shows probability of collision above an operator threshold. Usually a small along-track burn executed hours in advance, since a few centimetres per second is enough to move the encounter geometry.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('deorbit-burn', 'Deorbit Burn', 'aerospace', 'maneuvers', 'Retrograde burn that lowers perigee into the atmosphere.', 'Ends a mission by guaranteeing re-entry within a controlled window and, for large vehicles, over an uninhabited ocean corridor. End-of-life guidelines call for LEO objects to re-enter within 25 years, with 5 years now recommended by some regulators.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('escape-velocity', 'Escape Velocity', 'aerospace', 'maneuvers', 'Speed needed to leave a gravity well with no further thrust.', 'Equals the square root of 2 mu over r, about 11.2 km/s at Earth''s surface ignoring atmosphere, and about 3.2 km/s from LEO in addition to orbital speed already held.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('characteristic-energy', 'Characteristic Energy', 'aerospace', 'maneuvers', 'Twice the specific orbital energy of a departure trajectory.', 'Zero means exactly escape; positive values mean hyperbolic departure with excess speed. Launch vehicle performance for interplanetary missions is quoted as payload mass versus C3.', 'C3', 'km2/s2', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('launch-window', 'Launch Window', 'aerospace', 'maneuvers', 'Interval when geometry permits the planned trajectory.', 'For rendezvous it is set by plane alignment; for interplanetary flight by the synodic period, which is roughly 26 months for Mars. Missing a window can mean waiting years and paying more delta-v.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('porkchop-plot', 'Porkchop Plot', 'aerospace', 'maneuvers', 'Contour chart of transfer cost against departure and arrival dates.', 'Shows C3 or total delta-v across a grid of dates, with nested contours resembling a pork chop. The standard tool for selecting interplanetary launch periods.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('specific-impulse', 'Specific Impulse', 'aerospace', 'propulsion', 'Thrust per unit propellant weight flow; the efficiency of a rocket.', 'Roughly 450 seconds for a hydrogen-oxygen upper stage in vacuum, 300 to 340 for kerosene-oxygen, 300 to 320 for storable hypergolics, and 1,500 to 4,000 for electric thrusters. Higher specific impulse means less propellant for the same delta-v.', 'Isp', 'seconds', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('thrust', 'Thrust', 'aerospace', 'propulsion', 'Force produced by expelling mass, plus a pressure term at the nozzle exit.', 'Equals mass flow times exhaust velocity plus exit area times the difference between exit and ambient pressure. That second term is why an engine''s sea-level and vacuum thrust differ.', NULL, 'newtons', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('thrust-to-weight-ratio', 'Thrust-to-Weight Ratio', 'aerospace', 'propulsion', 'Thrust divided by vehicle weight; must exceed one to lift off.', 'First stages typically launch with a ratio of about 1.2 to 1.5. Too low wastes propellant fighting gravity, too high adds structural loads and aerodynamic stress.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('mass-ratio', 'Mass Ratio', 'aerospace', 'propulsion', 'Initial mass divided by final mass after the burn.', 'The term inside the logarithm of the rocket equation. Achievable mass ratio is limited by tank, structure, and engine mass, which is why staging exists.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('effective-exhaust-velocity', 'Effective Exhaust Velocity', 'aerospace', 'propulsion', 'Specific impulse expressed as a velocity.', 'Equal to specific impulse times standard gravity, about 4,400 m/s for a hydrogen-oxygen upper stage. It appears directly in the rocket equation.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('staging', 'Staging', 'aerospace', 'propulsion', 'Discarding empty structure during ascent to improve mass ratio.', 'Each stage carries only the tankage and engines it needs, so dry mass falls as the flight proceeds. Two or three stages are typical for orbital launch; more stages add complexity and separation risk.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('hypergolic-propellant', 'Hypergolic Propellant', 'aerospace', 'propulsion', 'Fuel and oxidiser that ignite on contact, needing no igniter.', 'Monomethylhydrazine with nitrogen tetroxide is common. Storable for years and highly reliable to restart, which suits attitude control, landers, and deep space main engines, at the cost of toxicity and ground handling burden.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('cryogenic-propellant', 'Cryogenic Propellant', 'aerospace', 'propulsion', 'Propellant stored as a deeply cold liquid, such as hydrogen or oxygen.', 'Offers high performance but boils off, so it needs insulation, venting, and late loading. Long-duration cryogenic storage is an active technology area for lunar and Mars architectures.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('solid-rocket-motor', 'Solid Rocket Motor', 'aerospace', 'propulsion', 'Pre-cast propellant grain that burns to a fixed thrust profile.', 'Simple, dense, and storable, delivering large thrust for boosters, but it cannot generally be throttled or shut down once ignited. Thrust profile is shaped by the grain geometry.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('monopropellant-thruster', 'Monopropellant Thruster', 'aerospace', 'propulsion', 'Single propellant decomposed over a catalyst bed.', 'Hydrazine over an iridium catalyst gives about 220 to 235 seconds of specific impulse with very simple plumbing, which suits attitude control and small station keeping burns. Green monopropellants are now flying as lower-toxicity replacements.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('ion-thruster', 'Ion Thruster', 'aerospace', 'propulsion', 'Electrostatic thruster accelerating ions through a gridded field.', 'Specific impulse of 3,000 seconds and above with thrust measured in tens to hundreds of millinewtons. Dawn used ion propulsion to orbit both Vesta and Ceres, which chemical propulsion could not have afforded.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('hall-effect-thruster', 'Hall Effect Thruster', 'aerospace', 'propulsion', 'Plasma thruster using crossed electric and magnetic fields.', 'Delivers 1,200 to 2,500 seconds of specific impulse at higher thrust density than gridded ion engines. Now the standard for geostationary orbit raising and for large LEO constellation station keeping.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('electric-propulsion', 'Electric Propulsion', 'aerospace', 'propulsion', 'Using electrical power rather than chemical energy to accelerate propellant.', 'Trades thrust for efficiency: transfers take months instead of hours, but propellant mass can drop by more than half. Available power sets the achievable thrust, so array size drives the design.', NULL, NULL, ARRAY['Solar electric propulsion']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('cold-gas-thruster', 'Cold Gas Thruster', 'aerospace', 'propulsion', 'Expelling stored pressurised gas with no combustion.', 'Specific impulse of roughly 50 to 70 seconds, but extremely simple, clean, and safe. Used on small satellites, for fine pointing, and for crewed extravehicular manoeuvring units.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('nuclear-thermal-propulsion', 'Nuclear Thermal Propulsion', 'aerospace', 'propulsion', 'Heating propellant with a fission reactor instead of combustion.', 'Ground-tested in the NERVA programme at roughly double the specific impulse of the best chemical engines. Under study again for crewed Mars transfers; no flight demonstration has occurred.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('solar-sail', 'Solar Sail', 'aerospace', 'propulsion', 'Propellantless thrust from solar radiation pressure.', 'Thrust is tiny, on the order of micronewtons per square metre near Earth, but continuous. IKAROS and LightSail 2 demonstrated controlled sail flight; NASA''s Advanced Composite Solar Sail System extended the technology.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('throttling', 'Throttling', 'aerospace', 'propulsion', 'Varying thrust in flight by modulating propellant flow.', 'Needed for landing, load relief through maximum dynamic pressure, and precise orbit insertion. Deep throttling is hard because injector and chamber stability degrade away from the design point.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('gimbal', 'Gimbal', 'aerospace', 'propulsion', 'Pivoting an engine to steer the thrust vector.', 'The primary control effector during powered flight. Gimbal range, rate, and actuator authority are sized against expected wind shear, thrust misalignment, and engine-out cases.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('nozzle-expansion-ratio', 'Nozzle Expansion Ratio', 'aerospace', 'propulsion', 'Exit area divided by throat area.', 'Larger ratios extract more performance in vacuum but cause flow separation at sea level. This is why upper stage engines have visibly larger bells than first stage engines of similar thrust.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('combustion-chamber-pressure', 'Combustion Chamber Pressure', 'aerospace', 'propulsion', 'Pressure at which propellants burn before expanding through the nozzle.', 'Higher chamber pressure allows more expansion in a given size, raising performance and thrust density, at the cost of turbomachinery, cooling, and structural demands.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('propellant-slosh', 'Propellant Slosh', 'aerospace', 'propulsion', 'Fluid motion inside partly filled tanks that disturbs attitude.', 'Can couple with the control system and destabilise the vehicle. Managed with baffles, diaphragms, and control laws tuned to the slosh modes.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('spacecraft-bus', 'Spacecraft Bus', 'aerospace', 'bus', 'The service platform that supports the payload.', 'Provides structure, power, thermal control, attitude control, propulsion, command and data handling, and communications. Reusing a qualified bus across missions is the main cost lever in satellite manufacture.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('attitude-determination-and-control-system', 'Attitude Determination and Control System', 'aerospace', 'bus', 'The system that senses and controls spacecraft orientation.', 'Sensors include star trackers, sun sensors, magnetometers, and gyroscopes; actuators include reaction wheels, magnetic torquers, and thrusters. Pointing accuracy requirements drive the whole design, from arcminutes for a communications satellite to milliarcseconds for a space telescope.', NULL, NULL, ARRAY['ADCS']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('reaction-wheel', 'Reaction Wheel', 'aerospace', 'bus', 'Spinning flywheel that exchanges angular momentum with the spacecraft.', 'Provides smooth, propellant-free pointing control. Wheels saturate as disturbance torques accumulate and must be desaturated with thrusters or magnetic torquers. Wheel failures have ended or reshaped several major missions.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('control-moment-gyroscope', 'Control Moment Gyroscope', 'aerospace', 'bus', 'Gimballed spinning rotor producing large control torque.', 'Delivers far more torque than a reaction wheel of similar mass, which suits large stations. The International Space Station uses four to hold attitude without propellant.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('magnetorquer', 'Magnetorquer', 'aerospace', 'bus', 'Coil that torques against the local magnetic field.', 'Cheap, has no moving parts, and needs only power, but produces torque only perpendicular to the field and only where the field is strong, which limits it to LEO. Widely used on small satellites and for wheel desaturation.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('star-tracker', 'Star Tracker', 'aerospace', 'bus', 'Camera that determines attitude by matching a star field to a catalogue.', 'Provides absolute three-axis attitude with arcsecond-class accuracy. Performance depends on avoiding bright body intrusion from the Sun, Earth, or Moon in the field of view.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('inertial-measurement-unit', 'Inertial Measurement Unit', 'aerospace', 'bus', 'Gyroscopes and accelerometers giving short-term attitude and rate.', 'Accurate over short intervals but subject to drift, so it is fused with absolute references such as star trackers and sun sensors in an estimator.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('spin-stabilisation', 'Spin Stabilisation', 'aerospace', 'bus', 'Holding orientation using the gyroscopic stiffness of a spinning body.', 'Simple and robust, used on early communications satellites and many upper stages. Pointing an instrument then requires despun platforms or accepting a scanning geometry.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('gravity-gradient-stabilisation', 'Gravity Gradient Stabilisation', 'aerospace', 'bus', 'Passive stabilisation using the tidal torque on an elongated body.', 'An elongated spacecraft tends to align its long axis with the local vertical. Requires no power, gives coarse accuracy, and is common on small technology demonstrators.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('electrical-power-subsystem', 'Electrical Power Subsystem', 'aerospace', 'bus', 'Generation, storage, regulation, and distribution of spacecraft power.', 'Sized for the worst case: peak load during eclipse at end of life, after array degradation. Includes solar arrays, batteries, regulators, and protection.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('solar-array', 'Solar Array', 'aerospace', 'bus', 'Photovoltaic panels converting sunlight into electrical power.', 'Triple-junction cells reach roughly 30 percent efficiency. Output falls with radiation damage, thermal cycling, and increasing distance from the Sun, which scales as inverse square, making solar power hard beyond Jupiter.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('radioisotope-thermoelectric-generator', 'Radioisotope Thermoelectric Generator', 'aerospace', 'bus', 'Power from the heat of radioisotope decay converted thermoelectrically.', 'Provides steady power independent of sunlight, which is why Voyager, Cassini, New Horizons, Curiosity, and Perseverance use it. Output declines predictably as the plutonium-238 source decays and thermocouples degrade.', NULL, NULL, ARRAY['RTG']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('eclipse-season', 'Eclipse Season', 'aerospace', 'bus', 'Period when a satellite passes through the primary''s shadow regularly.', 'Geostationary satellites experience daily eclipses of up to about 72 minutes near the equinoxes, sizing the battery. LEO spacecraft are eclipsed on most revolutions.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('thermal-control-subsystem', 'Thermal Control Subsystem', 'aerospace', 'bus', 'Keeping every component inside its allowed temperature range.', 'Passive means include multi-layer insulation, coatings, radiators, and heat pipes; active means include heaters and pumped loops. In vacuum, radiation is the only path off the vehicle, so radiator area is a hard design constraint.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('multi-layer-insulation', 'Multi-Layer Insulation', 'aerospace', 'bus', 'Stacked reflective films that block radiative heat transfer.', 'The familiar gold or silver blanketing. Its effectiveness depends on low-conductance spacing between layers, so seams, penetrations, and attachment points dominate real performance.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('command-and-data-handling', 'Command and Data Handling', 'aerospace', 'bus', 'The onboard computing that executes commands and manages data.', 'Runs the flight software, stores telemetry, sequences activities, and detects faults. Processors are radiation-hardened and generations behind consumer parts because reliability outweighs raw speed.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('fault-detection-isolation-and-recovery', 'Fault Detection, Isolation, and Recovery', 'aerospace', 'bus', 'Autonomous logic that reacts to anomalies without ground help.', 'Necessary when light time or coverage gaps prevent timely intervention. The typical safe response is to enter a protective mode, hold power-positive and thermally safe attitude, and wait for instructions.', NULL, NULL, ARRAY['FDIR']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('safe-mode', 'Safe Mode', 'aerospace', 'bus', 'Protective configuration entered after a detected fault.', 'Non-essential loads are shed, the spacecraft points to keep arrays illuminated, and it listens on a low-rate link. Science stops until operators diagnose and command a recovery.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('single-event-upset', 'Single Event Upset', 'aerospace', 'bus', 'Bit flip caused by a single energetic particle strike.', 'Mitigated with error detecting and correcting memory, redundancy, watchdogs, and periodic memory scrubbing. Rates rise sharply inside the radiation belts and during solar particle events.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('redundancy', 'Redundancy', 'aerospace', 'bus', 'Duplicate hardware or paths that preserve function after a failure.', 'Block redundancy duplicates whole strings; cross-strapping allows mixing units between strings. The design goal is no single point of failure for mission-critical functions.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('outgassing', 'Outgassing', 'aerospace', 'bus', 'Release of trapped gases from materials in vacuum.', 'Can contaminate optics, detectors, and thermal surfaces. Controlled through material selection, bake-out before launch, and venting paths that keep the plume away from sensitive surfaces.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('atomic-oxygen-erosion', 'Atomic Oxygen Erosion', 'aerospace', 'bus', 'Chemical erosion of surfaces by monatomic oxygen in LEO.', 'Highly reactive atomic oxygen degrades polymers and some coatings on ram-facing surfaces. Protective coatings and material choices are required for long LEO missions.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('cubesat', 'CubeSat', 'aerospace', 'bus', 'Standardised small satellite built from 10 cm units.', 'One unit is a 10 cm cube of roughly 1.3 kg; larger craft are described as 3U, 6U, or 12U. The standard interface and deployer made low-cost access routine for universities and startups.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('telemetry-tracking-and-command', 'Telemetry, Tracking, and Command', 'aerospace', 'comms', 'The link that carries health data down and commands up.', 'Kept simple and robust, often with an omnidirectional antenna, so contact survives attitude loss. Ranging on the same link provides orbit determination measurements.', NULL, NULL, ARRAY['TT&C']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('link-budget', 'Link Budget', 'aerospace', 'comms', 'Accounting of gains and losses that shows whether a link closes.', 'Sums transmitter power, antenna gains, free space loss, atmospheric and pointing losses, and receiver noise to yield a signal-to-noise margin. Positive margin at the required data rate means the link closes.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('free-space-path-loss', 'Free Space Path Loss', 'aerospace', 'comms', 'Signal spreading loss that grows with distance and frequency.', 'Increases as the square of both range and frequency. It is why deep space missions need large dish antennas at both ends and why data rates fall steeply as a probe recedes.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('effective-isotropic-radiated-power', 'Effective Isotropic Radiated Power', 'aerospace', 'comms', 'Transmitter power combined with antenna gain in the pointing direction.', 'A single figure of merit for the transmit side of the link. Regulators cap EIRP density to protect other users of the band.', NULL, NULL, ARRAY['EIRP']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('gain-to-noise-temperature-ratio', 'Gain-to-Noise-Temperature Ratio', 'aerospace', 'comms', 'Figure of merit for a receiving station.', 'Combines antenna gain with system noise temperature. Low-noise amplifiers, cryogenic front ends, and large apertures all raise it, which is how faint deep space carriers are recovered.', 'G/T', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('s-band', 'S-Band', 'aerospace', 'comms', 'About 2 to 4 GHz; standard for command, telemetry, and ranging.', 'Rain effects are small and antennas are modest, so it suits robust low-rate links. Widely used for spacecraft housekeeping and for crewed vehicle voice and data.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('x-band', 'X-Band', 'aerospace', 'comms', 'About 8 to 12 GHz; the workhorse for deep space and imaging downlink.', 'Offers more bandwidth than S-band with manageable weather losses. The Deep Space Network''s primary science downlink band for most planetary missions.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('ka-band', 'Ka-Band', 'aerospace', 'comms', 'About 26 to 40 GHz; high data rate at the cost of rain sensitivity.', 'Supports the highest science return rates and broadband services, but rain fade requires larger margins, site diversity, or adaptive coding and modulation.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('uhf-relay', 'UHF Relay', 'aerospace', 'comms', 'Short-range link used between surface assets and orbiters.', 'Mars rovers relay most of their data through orbiters over UHF rather than talking to Earth directly, because the relay path needs far less power for far more throughput.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('doppler-tracking', 'Doppler Tracking', 'aerospace', 'comms', 'Measuring range rate from the frequency shift of the carrier.', 'Two-way coherent Doppler gives extremely precise line-of-sight velocity, which is the backbone of deep space navigation and of gravity science experiments.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('ranging', 'Ranging', 'aerospace', 'comms', 'Measuring distance from the round-trip time of a modulated signal.', 'Combined with Doppler and delta differential one-way ranging, it reduces orbit determination uncertainty to metres for Earth orbiters and kilometres across the solar system.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('deep-space-network', 'Deep Space Network', 'aerospace', 'comms', 'Three-site global antenna network for deep space communications.', 'Complexes near Goldstone, Madrid, and Canberra are spaced about 120 degrees apart so at least one always sees a given deep space target. Antennas up to 70 m support tracking, telemetry, command, and radio science.', NULL, NULL, ARRAY['DSN']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('ground-station-pass', 'Ground Station Pass', 'aerospace', 'comms', 'The window while a spacecraft is visible from a ground antenna.', 'A LEO pass typically lasts 5 to 12 minutes above a usable elevation, a handful of times per day per station, which caps how much data one site can recover.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('store-and-forward', 'Store and Forward', 'aerospace', 'comms', 'Recording data onboard for downlink during the next contact.', 'Necessary because most spacecraft are out of contact most of the time. Onboard storage and downlink capacity together set the effective science data rate.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('forward-error-correction', 'Forward Error Correction', 'aerospace', 'comms', 'Coding that lets the receiver repair errors without retransmission.', 'Turbo and low-density parity check codes operate within a fraction of a decibel of the theoretical limit, which directly buys data rate or antenna size on deep space links.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('light-time-delay', 'Light Time Delay', 'aerospace', 'comms', 'One-way signal travel time, which forbids real-time control at distance.', 'About 1.3 seconds to the Moon, 4 to 24 minutes to Mars depending on geometry, and hours to the outer solar system. Entries, landings, and flybys must therefore be autonomous.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('beacon-tone', 'Beacon Tone', 'aerospace', 'comms', 'Minimal signal conveying spacecraft state with almost no bandwidth.', 'A small set of distinguishable tones tells operators whether the spacecraft is nominal or needs attention, allowing routine monitoring with very short antenna time.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('gravity-turn', 'Gravity Turn', 'aerospace', 'launch', 'Ascent profile that uses gravity to pitch the vehicle over.', 'After a short vertical rise the vehicle pitches slightly and then lets gravity rotate the velocity vector, keeping the airframe near zero angle of attack. This minimises steering losses and aerodynamic loads.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('maximum-dynamic-pressure', 'Maximum Dynamic Pressure', 'aerospace', 'launch', 'Peak aerodynamic pressure during ascent.', 'Occurs roughly 60 to 90 seconds into flight where rising speed and falling air density peak together. Vehicles often throttle down through this region to limit structural loads.', NULL, NULL, ARRAY['Max Q']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('gravity-loss', 'Gravity Loss', 'aerospace', 'launch', 'Delta-v spent fighting gravity rather than gaining speed.', 'Every second thrusting against gravity costs about 9.8 m/s of potential velocity. Higher initial thrust-to-weight and prompt pitchover reduce the penalty; it is a major part of the difference between ideal and actual ascent delta-v.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('drag-loss', 'Drag Loss', 'aerospace', 'launch', 'Delta-v lost to atmospheric drag during ascent.', 'Typically a few hundred metres per second, small next to gravity loss but enough to shape fairing design and the ascent trajectory.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('payload-fairing', 'Payload Fairing', 'aerospace', 'launch', 'Aerodynamic shroud protecting the payload during ascent.', 'Shields against dynamic pressure, aeroacoustic loads, and heating, then separates once outside the sensible atmosphere. Fairing volume often constrains spacecraft design more than mass does.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('stage-separation', 'Stage Separation', 'aerospace', 'launch', 'Releasing a spent stage and starting the next.', 'Uses pyrotechnic or pneumatic mechanisms, sometimes with retro-thrust or spring pushers to guarantee clean separation. A critical event with little margin for recovery if it fails.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('coast-phase', 'Coast Phase', 'aerospace', 'launch', 'Unpowered interval between burns during ascent.', 'Lets the vehicle reach the correct point in the orbit before the circularisation or transfer burn. Requires attitude control, thermal management, and propellant settling before restart.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('launch-azimuth', 'Launch Azimuth', 'aerospace', 'launch', 'Compass heading at liftoff, which sets the achievable inclination.', 'Chosen from the launch site latitude and the target inclination, constrained by range safety corridors over populated areas. Eastward launches gain the most from Earth''s rotation.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('dogleg-maneuver', 'Dogleg Maneuver', 'aerospace', 'launch', 'In-flight azimuth change to reach an otherwise blocked inclination.', 'Steering out of the initial heading avoids overflight restrictions but costs performance, so it is used only when geography leaves no better option.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('range-safety', 'Range Safety', 'aerospace', 'launch', 'Rules and systems that protect people and property during launch.', 'Includes instantaneous impact point monitoring and an autonomous or commanded flight termination capability, plus keep-out zones on land, sea, and air.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('hold-down-and-release', 'Hold-Down and Release', 'aerospace', 'launch', 'Restraining the vehicle until thrust and health are verified.', 'Engines start, sensors confirm nominal chamber pressure and thrust, and only then do the restraints release. This protects against a low-thrust liftoff.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('entry-descent-and-landing', 'Entry, Descent, and Landing', 'aerospace', 'launch', 'The sequence from atmospheric interface to touchdown.', 'Combines a heat shield, deceleration, guidance, parachutes or propulsion, and touchdown hardware. At Mars the whole sequence runs autonomously in about seven minutes because of light time delay.', NULL, NULL, ARRAY['EDL']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('ballistic-coefficient', 'Ballistic Coefficient', 'aerospace', 'launch', 'Mass divided by drag coefficient times reference area.', 'A low value decelerates high in the atmosphere, useful for entry vehicles and for predicting satellite decay. It is the parameter that makes drag prediction tractable for catalogued objects.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('aerodynamic-heating', 'Aerodynamic Heating', 'aerospace', 'launch', 'Heat load generated by compressing and shearing air during entry.', 'Peak heat rate and total heat load size the thermal protection system. Convective heating dominates at Earth entry speeds; radiative heating becomes important at very high entry velocities.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('thermal-protection-system', 'Thermal Protection System', 'aerospace', 'launch', 'Materials that keep entry heat out of the structure.', 'Ablators such as phenolic impregnated carbon char away to carry heat off; reusable tiles and reinforced carbon-carbon radiate it instead. Selection follows the expected heat rate and load.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('blackout-period', 'Blackout Period', 'aerospace', 'launch', 'Communications interruption caused by entry plasma.', 'Ionised gas around the vehicle attenuates radio signals for part of the entry. Relay geometry and band selection can shorten it, but planning assumes a gap.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('skip-entry', 'Skip Entry', 'aerospace', 'launch', 'Entry profile that briefly exits and re-enters the atmosphere.', 'Extends downrange control and spreads the heat load over two passes, which reduces peak deceleration. Used by Orion on Artemis I to improve landing accuracy.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('terminal-descent', 'Terminal Descent', 'aerospace', 'launch', 'Final phase from parachute release or hover to touchdown.', 'Options include retro-propulsion, airbags, crushable structure, or a sky crane. Precision landing needs terrain relative navigation and hazard detection during this phase.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('van-allen-belts', 'Van Allen Belts', 'aerospace', 'environment', 'Two regions of trapped energetic particles around Earth.', 'The inner belt is proton-dominated from roughly 1,000 to 6,000 km; the outer belt is electron-dominated from roughly 13,000 to 60,000 km. Spacecraft either avoid dwell time here or accept a hardening and shielding penalty.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('south-atlantic-anomaly', 'South Atlantic Anomaly', 'aerospace', 'environment', 'Region where the inner radiation belt dips to low altitude.', 'Earth''s offset magnetic field brings trapped protons down to LEO altitudes over the South Atlantic. Instruments are often safed during passes because upset and noise rates spike.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('kp-index', 'Kp Index', 'aerospace', 'environment', 'Planetary index of global geomagnetic activity, 0 to 9.', 'Derived from ground magnetometer measurements in three-hour intervals. Values of 5 and above indicate storm conditions with aurora at lower latitudes, increased satellite drag, and possible navigation and radio degradation.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('solar-wind', 'Solar Wind', 'aerospace', 'environment', 'Continuous outflow of plasma from the Sun''s corona.', 'Typically 300 to 800 km/s with a few particles per cubic centimetre near Earth, carrying the interplanetary magnetic field. Its speed and field orientation govern how strongly it couples to the magnetosphere.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('coronal-mass-ejection', 'Coronal Mass Ejection', 'aerospace', 'environment', 'Large eruption of plasma and magnetic field from the Sun.', 'Can reach Earth in roughly 15 to 72 hours and drive geomagnetic storms that affect satellites, aviation at high latitudes, and power grids. Arrival time and severity are forecast from coronagraph imagery and upstream monitors.', NULL, NULL, ARRAY['CME']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('solar-flare', 'Solar Flare', 'aerospace', 'environment', 'Sudden localised brightening on the Sun, classified A to X.', 'X-rays arrive at light speed and immediately disturb the ionosphere, causing high-frequency radio blackouts. Each letter class is a tenfold increase in peak X-ray flux.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('solar-energetic-particle-event', 'Solar Energetic Particle Event', 'aerospace', 'environment', 'Burst of accelerated protons and ions from solar activity.', 'Can reach Earth within tens of minutes, raising radiation dose for crews and upset rates for electronics. The main radiation-safety driver for crewed missions beyond LEO.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('galactic-cosmic-rays', 'Galactic Cosmic Rays', 'aerospace', 'environment', 'High-energy particles from outside the solar system.', 'Low flux but extremely energetic, so shielding is only partially effective and can produce secondary particles. The dominant long-term dose contributor on interplanetary transits.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('total-ionising-dose', 'Total Ionising Dose', 'aerospace', 'environment', 'Cumulative radiation absorbed over a mission.', 'Measured in rads or grays and used to qualify parts. Threshold shifts and leakage current in semiconductors accumulate until performance leaves specification, which sets radiation-limited design life.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('spacecraft-charging', 'Spacecraft Charging', 'aerospace', 'environment', 'Accumulation of electric charge on surfaces or in dielectrics.', 'Differential charging can produce arcing that damages solar arrays and injects noise into electronics. Managed with conductive coatings, grounding straps, and bonding practices.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('micrometeoroid-and-orbital-debris', 'Micrometeoroid and Orbital Debris', 'aerospace', 'environment', 'Small natural and artificial particles that can perforate structures.', 'Millimetre-scale impacts at kilometres per second are the design case for Whipple shields and pressure vessel protection. Larger tracked objects are handled by avoidance manoeuvres instead.', NULL, NULL, ARRAY['MMOD']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('kessler-syndrome', 'Kessler Syndrome', 'aerospace', 'environment', 'Runaway debris growth from collision-generated fragments.', 'Described by Donald Kessler in 1978: above a certain object density, collisions generate debris faster than it decays, making some orbital bands progressively harder to use.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('conjunction-assessment', 'Conjunction Assessment', 'aerospace', 'environment', 'Screening predicted close approaches for collision risk.', 'Combines catalogue orbits with covariance to compute miss distance and probability of collision. Operators act above defined thresholds, usually with a small along-track burn days or hours out.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('thermosphere-density-variation', 'Thermosphere Density Variation', 'aerospace', 'environment', 'Large swings in upper atmosphere density that change drag.', 'Density at 400 km can vary by an order of magnitude with solar activity and geomagnetic storms. This is the biggest error source in LEO decay and conjunction prediction.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('magnetosphere', 'Magnetosphere', 'aerospace', 'environment', 'The region where Earth''s magnetic field controls plasma motion.', 'Compressed to about 10 Earth radii on the dayside and drawn into a long tail on the nightside. It shields the surface from most solar wind particles and channels the rest towards the poles.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('ionosphere', 'Ionosphere', 'aerospace', 'environment', 'Ionised layer of the upper atmosphere from about 60 to 1,000 km.', 'Refracts and delays radio signals, which is the largest single error source for single-frequency satellite navigation. Dual-frequency receivers and correction models remove most of it.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('near-earth-object', 'Near-Earth Object', 'aerospace', 'environment', 'Asteroid or comet with a perihelion below 1.3 astronomical units.', 'Tracked by surveys and catalogued by the Center for Near Earth Object Studies. A subset classed as potentially hazardous have minimum orbit intersection distances below 0.05 astronomical units and absolute magnitude brighter than 22.', NULL, NULL, ARRAY['NEO']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('lunar-distance', 'Lunar Distance', 'aerospace', 'environment', 'Average Earth-Moon distance, about 384,400 km, used for close approaches.', 'A convenient scale for asteroid encounters. Passes inside one lunar distance are common for small objects and are reported routinely without implying hazard.', NULL, NULL, ARRAY['LD']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('astronomical-unit', 'Astronomical Unit', 'aerospace', 'environment', 'Defined as exactly 149,597,870.7 km.', 'The standard unit for solar system distances. Mars orbits at about 1.52, Jupiter at about 5.2, and Neptune at about 30.1 astronomical units.', NULL, NULL, ARRAY['AU']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('planetary-protection', 'Planetary Protection', 'aerospace', 'environment', 'Preventing biological cross-contamination between worlds.', 'Missions are assigned categories with bioburden and trajectory-biasing requirements, both to protect potentially habitable environments and to keep future life detection results trustworthy.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('orbit-determination', 'Orbit Determination', 'aerospace', 'operations', 'Estimating an orbit from tracking measurements.', 'Fits observations such as range, Doppler, angles, or global navigation satellite data to a dynamic model using least squares or filtering. The result includes a covariance describing how well the state is known.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('covariance', 'Covariance', 'aerospace', 'operations', 'Statistical description of uncertainty in an estimated state.', 'Represented as an ellipsoid in position and velocity, usually largest along track. Realistic covariance is what makes probability of collision meaningful.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('norad-catalogue-number', 'NORAD Catalogue Number', 'aerospace', 'operations', 'Sequential identifier assigned to a tracked space object.', 'Assigned in order of cataloguing, so lower numbers are older objects. The International Space Station is 25544. Alphanumeric extensions were introduced as the catalogue grew past five digits.', NULL, NULL, ARRAY['Satellite Catalog Number','SATCAT']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('international-designator', 'International Designator', 'aerospace', 'operations', 'Identifier based on launch year, launch number, and object piece.', 'Formatted as year, sequential launch of that year, and a letter for the piece, for example 1998-067A for the first International Space Station element. It links every object back to its launch.', NULL, NULL, ARRAY['COSPAR ID','Launch ID']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('two-body-propagation', 'Two-Body Propagation', 'aerospace', 'operations', 'Predicting motion using only the primary''s point-mass gravity.', 'Fast and analytic, adequate for visualisation over short spans. Operational prediction adds oblateness, drag, third-body gravity, and radiation pressure.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('ephemeris', 'Ephemeris', 'aerospace', 'operations', 'Tabulated positions of a body over time.', 'Planetary and spacecraft ephemerides such as the JPL Development Ephemeris and Horizons products are the reference against which observations and pointing predictions are computed.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('pass-prediction', 'Pass Prediction', 'aerospace', 'operations', 'Computing when a spacecraft will be visible from a site.', 'Propagates the orbit, converts to topocentric coordinates, and reports rise, culmination, and set times with azimuth, elevation, and range. Optical visibility additionally requires a dark site and a sunlit spacecraft.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('coordinated-universal-time', 'Coordinated Universal Time', 'aerospace', 'operations', 'The civil time standard used for all mission timelines.', 'Kept within a second of Earth rotation by leap seconds. Astrodynamics also uses Terrestrial Time and Barycentric Dynamical Time, and confusing time systems is a classic source of trajectory error.', NULL, NULL, ARRAY['UTC']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('julian-date', 'Julian Date', 'aerospace', 'operations', 'Continuous day count used to avoid calendar arithmetic.', 'Counts days from 4713 BC in the Julian proleptic calendar. Element set epochs and ephemeris queries are commonly expressed in Julian or modified Julian dates.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('ground-segment', 'Ground Segment', 'aerospace', 'operations', 'The antennas, control centre, and networks that operate a mission.', 'Includes tracking stations, mission operations and science centres, scheduling, and archives. It is a substantial share of total life cycle cost and is planned alongside the flight system.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('flight-rule', 'Flight Rule', 'aerospace', 'operations', 'Pre-agreed decision that removes real-time debate.', 'Documents the action for a defined condition, for example when to wave off an approach. Written and reviewed in advance so time-critical calls are consistent and defensible.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('go-or-no-go-poll', 'Go or No-Go Poll', 'aerospace', 'operations', 'Structured readiness check before a critical event.', 'Each console operator reports readiness against defined criteria. Any no-go stops the sequence until it is resolved or explicitly waived.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('commissioning-phase', 'Commissioning Phase', 'aerospace', 'operations', 'Post-launch period of switching on and calibrating the spacecraft.', 'Deployments, subsystem activation, instrument calibration, and orbit trimming happen before routine operations begin. It can run from weeks to six months for complex observatories.', NULL, NULL, ARRAY['In-orbit checkout']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('technology-readiness-level', 'Technology Readiness Level', 'aerospace', 'operations', 'Nine-step scale for the maturity of a technology.', 'Level 1 is basic principles and level 9 is flight proven in an operational environment. Programmes commonly require a defined level before a design review, which shapes when new technology can be baselined.', NULL, NULL, ARRAY['TRL']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('mission-design-review-cycle', 'Mission Design Review Cycle', 'aerospace', 'operations', 'Formal gates from concept study to launch readiness.', 'Typically mission concept review, system requirements review, preliminary and critical design reviews, then integration, test, and flight readiness. Defined in the NASA Systems Engineering Handbook lifecycle.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('mass-margin', 'Mass Margin', 'aerospace', 'operations', 'Reserve between current best estimate mass and the allowable limit.', 'Held large early and consumed as the design matures, because mass reliably grows. Running out late in development forces performance cuts or a launch vehicle change.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('design-reference-mission', 'Design Reference Mission', 'aerospace', 'operations', 'Representative mission profile used to size and verify a system.', 'A concrete scenario with timeline, environments, and data volumes, so requirements can be traced to something operational rather than argued in the abstract.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('end-of-life-passivation', 'End of Life Passivation', 'aerospace', 'operations', 'Making a retired spacecraft inert.', 'Venting propellant, discharging batteries, and disabling pressure and energy sources so the object cannot explode and generate debris years later. A core debris mitigation requirement.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('angle-of-attack', 'Angle of Attack', 'aviation', 'aviation', 'The angle between the wing chord and the oncoming airflow.', 'Lift rises with angle of attack until the flow separates from the upper surface. Launch vehicles fly near zero angle of attack through peak loads to limit side forces.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('stall', 'Stall', 'aviation', 'aviation', 'Loss of lift when the airflow separates from a wing.', 'Happens past the critical angle of attack, regardless of airspeed. Recovery means lowering the nose to reduce the angle of attack.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('mach-number', 'Mach Number', 'aviation', 'aviation', 'Speed divided by the local speed of sound.', 'Below about Mach 0.8 flow is subsonic, around Mach 1 transonic, above 5 hypersonic. The speed of sound falls with temperature, so the same true speed gives a higher Mach number at altitude.', 'M', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('lift-to-drag-ratio', 'Lift-to-Drag Ratio', 'aviation', 'aviation', 'Lift divided by drag; a measure of aerodynamic efficiency.', 'Sets glide range. Airliners reach roughly 15 to 20; the Space Shuttle orbiter was close to 1 at hypersonic speed and about 4.5 on final approach (approximate).', 'L/D', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('dynamic-pressure', 'Dynamic Pressure', 'aviation', 'aviation', 'The pressure from moving through air, one half of density times speed squared.', 'Peaks during ascent at Max Q. Structural and control loads scale with it.', 'q', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('indicated-airspeed', 'Indicated Airspeed', 'aviation', 'aviation', 'Airspeed read from the pitot static system without corrections.', 'What the wing actually feels, so stall and structural limits are quoted in it. True airspeed is higher at altitude.', 'IAS', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('flight-level', 'Flight Level', 'aviation', 'aviation', 'Altitude in hundreds of feet based on standard pressure.', 'FL350 means 35,000 feet with the altimeter set to 1013.25 hPa, so all aircraft above the transition altitude share one reference.', 'FL', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('center-of-pressure', 'Center of Pressure', 'aviation', 'aviation', 'The point where the total aerodynamic force acts.', 'For stable flight it sits behind the center of gravity. Rockets add fins to move it aft.', 'CP', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('boundary-layer', 'Boundary Layer', 'aviation', 'aviation', 'The thin layer of air slowed by friction next to a surface.', 'It can be smooth (laminar) or turbulent. Turbulent boundary layers greatly raise heating on reentry vehicles.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('sonic-boom', 'Sonic Boom', 'aviation', 'aviation', 'The shock wave pressure jump heard when a vehicle flies faster than sound.', 'Returning Falcon 9 boosters and the Space Shuttle produced audible double booms near landing sites.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('apparent-magnitude', 'Apparent magnitude', 'astronomy', 'stars-galaxies', 'How bright a star looks from Earth. Smaller numbers are brighter.', 'The scale is logarithmic: a difference of 5 magnitudes is a brightness ratio of exactly 100. The Sun is about −26.7, Sirius about −1.5, and the faintest stars visible to the naked eye about +6.', 'm', 'mag', ARRAY['m']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('absolute-magnitude', 'Absolute magnitude', 'astronomy', 'stars-galaxies', 'The apparent magnitude a star would have at a standard distance of 10 parsecs.', 'Absolute magnitude lets astronomers compare intrinsic brightness regardless of distance. Together with apparent magnitude it gives distance through the distance modulus.', 'M', 'mag', ARRAY['M']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('luminosity', 'Luminosity', 'astronomy', 'stars-galaxies', 'Total energy a star radiates each second, across all wavelengths.', 'Measured in watts or in solar luminosities (the Sun is about 3.8 × 10²⁶ W). Luminosity depends on radius and surface temperature through the Stefan–Boltzmann law.', 'L', 'W or L☉', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('parallax', 'Parallax', 'astronomy', 'stars-galaxies', 'Apparent shift of a nearby star against distant background stars as Earth orbits the Sun.', 'Trigonometric parallax is the most direct way to measure distance. The distance in parsecs is 1 divided by the parallax angle in arcseconds.', 'p', 'arcsec', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('parsec', 'Parsec', 'astronomy', 'stars-galaxies', 'The distance at which one astronomical unit subtends one arcsecond; about 3.26 light-years.', 'The parsec is the standard distance unit in astronomy. Kiloparsecs and megaparsecs measure galactic and intergalactic distances.', NULL, 'pc', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('light-year', 'Light-year', 'astronomy', 'stars-galaxies', 'The distance light travels in one Julian year, about 9.46 × 10¹² km.', 'A distance unit, not a time unit. Proxima Centauri, the nearest star beyond the Sun, is about 4.2 light-years away.', NULL, 'ly', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('main-sequence', 'Main sequence', 'astronomy', 'stars-galaxies', 'The band of stars that fuse hydrogen into helium in their cores, where most stars spend their lives.', 'On the Hertzsprung–Russell diagram, more massive main-sequence stars are hotter, more luminous, and live shorter lives. The Sun is a main-sequence star.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('red-giant', 'Red giant', 'astronomy', 'stars-galaxies', 'A late-stage star that has expanded and cooled after exhausting its core hydrogen.', 'Hydrogen burning in a shell around the core drives the expansion. The Sun is expected to become a red giant in roughly five billion years.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('white-dwarf', 'White dwarf', 'astronomy', 'stars-galaxies', 'Dense, Earth-sized remnant of a low- to medium-mass star, held up by electron degeneracy pressure.', 'A white dwarf no longer fuses hydrogen and cools slowly over billions of years. Typical masses are about 0.5 to 0.6 solar masses.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('neutron-star', 'Neutron star', 'astronomy', 'stars-galaxies', 'Extremely dense remnant of a massive star, made mostly of neutrons after a core-collapse supernova.', 'Typical radius is about 10 to 12 km and mass 1.2 to 2 solar masses. Rotating neutron stars can appear as pulsars.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('supernova', 'Supernova', 'astronomy', 'stars-galaxies', 'Explosive death of a star that releases enormous energy and disperses heavy elements.', 'Type Ia supernovae come from white dwarfs in binary systems and serve as standard candles for distance measurement. Core-collapse supernovae end the lives of massive stars.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('nebula', 'Nebula', 'astronomy', 'stars-galaxies', 'A cloud of gas and dust in space. Emission, reflection, dark, and planetary nebulae are the main types.', 'Emission nebulae glow because nearby hot stars ionise their gas. Dark nebulae block light from the stars behind them. Planetary nebulae are shells cast off by dying stars.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('galaxy', 'Galaxy', 'astronomy', 'stars-galaxies', 'A gravitationally bound system of stars, gas, dust, and dark matter. The Milky Way is one of billions.', 'The Hubble sequence sorts galaxies into spiral, barred spiral, elliptical, lenticular, and irregular types.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('milky-way', 'Milky Way', 'astronomy', 'stars-galaxies', 'The barred spiral galaxy that contains the Sun, roughly 100,000 light-years across.', 'The Sun lies about 26,000 light-years from the galactic centre. The name also refers to the faint band of light visible across a dark night sky.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('redshift', 'Redshift', 'astronomy', 'stars-galaxies', 'Stretching of light toward longer wavelengths, caused by recession or by the expansion of space.', 'Redshift z = (λobserved − λemitted) / λemitted. It is the main evidence that the universe is expanding.', 'z', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('hubble-s-law', 'Hubble''s law', 'astronomy', 'stars-galaxies', 'Distant galaxies recede at a speed proportional to their distance: v = H₀ × d.', 'H₀ is the Hubble constant. Its exact value is still debated between measurement methods, with values near 70 km/s/Mpc in common use.', 'H₀', 'km/s/Mpc', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('pulsar', 'Pulsar', 'astronomy', 'stars-galaxies', 'A rapidly rotating neutron star that sweeps beams of radio emission past Earth, seen as regular pulses.', 'Pulsars are among the most precisely timed objects known. Their timing has been used to test general relativity.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('stellar-black-hole', 'Stellar black hole', 'astronomy', 'stars-galaxies', 'A black hole formed when a massive star collapses. Its mass is typically above about three solar masses.', 'The event horizon sits at the Schwarzschild radius, R = 2GM/c². Nothing, including light, can escape from inside it.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('binary-star', 'Binary star', 'astronomy', 'stars-galaxies', 'Two stars that orbit a common centre of mass.', 'Measuring binary orbits is one of the few direct ways to find a star''s mass.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('cosmic-microwave-background', 'Cosmic microwave background', 'astronomy', 'stars-galaxies', 'Relic thermal radiation from about 380,000 years after the Big Bang, now at about 2.7 K.', 'The CMB is nearly uniform across the sky, with tiny temperature fluctuations that seeded galaxies and clusters.', NULL, 'K', ARRAY['CMB']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('dark-matter', 'Dark matter', 'astronomy', 'stars-galaxies', 'Unseen matter inferred from its gravity on galaxies and clusters. It neither emits nor absorbs light.', 'Its nature is unknown. Rotation curves of spiral galaxies are among the main evidence for it.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('dark-energy', 'Dark energy', 'astronomy', 'stars-galaxies', 'The cause of the accelerating expansion of the universe. Its nature is unknown.', 'In the standard cosmological model, dark energy makes up roughly two-thirds of the total energy content of the universe.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('constellation', 'Constellation', 'astronomy', 'stars-galaxies', 'One of 88 officially recognised regions of the sky, named after star patterns.', 'Constellations are sky regions for navigation and reference, not physical groups of stars. Their stars can be at very different distances.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('hertzsprung-russell-diagram', 'Hertzsprung–Russell diagram', 'astronomy', 'stars-galaxies', 'Plot of luminosity against surface temperature for stars. It shows the main sequence, giants, and white dwarfs.', 'Stellar evolution is traced as paths across the diagram. Stars of different masses occupy different regions.', NULL, NULL, ARRAY['HR diagram']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('terrestrial-planet', 'Terrestrial planet', 'astronomy', 'solar-system', 'A rocky planet with a solid surface: Mercury, Venus, Earth, and Mars.', 'Terrestrial planets are denser and smaller than the giants, and have few or no large moons.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('gas-giant', 'Gas giant', 'astronomy', 'solar-system', 'A massive planet made mostly of hydrogen and helium: Jupiter and Saturn.', 'Gas giants have deep atmospheres with no solid surface. Jupiter is more than twice as massive as all the other planets combined.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('ice-giant', 'Ice giant', 'astronomy', 'solar-system', 'A planet with a deep icy mantle above a rocky core: Uranus and Neptune.', 'Ice giants contain more water, ammonia, and methane than the gas giants, and their magnetic fields are strongly tilted.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('asteroid-belt', 'Asteroid belt', 'astronomy', 'solar-system', 'The region between Mars and Jupiter where most asteroids orbit the Sun.', 'Despite its reputation, the belt is sparse. Its total mass is less than that of Earth''s Moon.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('kuiper-belt', 'Kuiper belt', 'astronomy', 'solar-system', 'A region of icy bodies beyond Neptune''s orbit, which includes Pluto.', 'Short-period comets are thought to come from the Kuiper belt, which extends from about 30 to 50 astronomical units.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('comet', 'Comet', 'astronomy', 'solar-system', 'A small icy body that develops a glowing coma and tail as it approaches the Sun.', 'Outgassing from the nucleus forms the coma and tail. Tails always point away from the Sun, pushed by the solar wind and radiation pressure.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('albedo', 'Albedo', 'astronomy', 'solar-system', 'The fraction of incident sunlight a surface reflects. Earth''s average is about 0.3.', 'Albedo controls how much energy a planet absorbs, which affects its temperature. Snow and ice have high albedo; deep ocean has low albedo.', 'A', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('axial-tilt', 'Axial tilt', 'astronomy', 'solar-system', 'The angle between a planet''s rotation axis and the normal to its orbit. Earth''s is about 23.4°.', 'Axial tilt, not distance from the Sun, is the main cause of Earth''s seasons.', NULL, '°', ARRAY['obliquity']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('exoplanet', 'Exoplanet', 'astronomy', 'solar-system', 'A planet orbiting a star other than the Sun. Thousands have been confirmed.', 'The first confirmed exoplanets orbit a pulsar and a Sun-like star, both discovered in the 1990s.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('transit-method', 'Transit method', 'astronomy', 'solar-system', 'Detects an exoplanet from the small, regular dip in starlight as it passes in front of its star.', 'The dip''s depth gives the planet''s size relative to the star. Transit surveys such as Kepler found most known exoplanets.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('radial-velocity-method', 'Radial velocity method', 'astronomy', 'solar-system', 'Detects an exoplanet from the Doppler wobble it causes in its star''s motion.', 'The method gives the planet''s minimum mass. It is complementary to the transit method, which gives size.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('habitable-zone', 'Habitable zone', 'astronomy', 'solar-system', 'The range of distances from a star where liquid water could exist on a planet''s surface.', 'Also called the Goldilocks zone. Its location depends on the star''s luminosity and on the planet''s atmosphere.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('refracting-telescope', 'Refracting telescope', 'astronomy', 'observing', 'A telescope that focuses light with lenses. Chromatic aberration is its main limit.', 'Colour fringing comes from lenses bending different wavelengths by different amounts. Achromatic and apochromatic designs reduce it.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('reflecting-telescope', 'Reflecting telescope', 'astronomy', 'observing', 'A telescope that collects light with a curved mirror. Most large research telescopes are reflectors.', 'Mirrors avoid chromatic aberration and can be made much larger than lenses. Newtonian and Cassegrain are common reflector designs.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('aperture', 'Aperture', 'astronomy', 'observing', 'The diameter of a telescope''s main light-collecting element. It sets light-gathering power and resolution.', 'Doubling the aperture quadruples the light collected. Aperture also sets the diffraction limit on resolution.', NULL, 'mm or m', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('angular-resolution', 'Angular resolution', 'astronomy', 'observing', 'The smallest angular separation a telescope can distinguish, approximately 1.22 λ/D.', 'This is the Rayleigh criterion for a circular aperture: λ is the wavelength and D the aperture diameter. Atmospheric turbulence often limits ground telescopes more than diffraction does.', NULL, 'rad or arcsec', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('adaptive-optics', 'Adaptive optics', 'astronomy', 'observing', 'Deformable mirrors that cancel atmospheric turbulence in real time, sharpening images from ground telescopes.', 'A guide star, natural or laser, measures the distortion, and the mirror is reshaped many times per second.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('spectroscopy', 'Spectroscopy', 'astronomy', 'observing', 'Splitting light into its wavelengths to reveal composition, temperature, velocity, and other properties.', 'Absorption and emission lines are the fingerprints of elements. Doppler shifts of those lines measure radial velocity.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('interferometry', 'Interferometry', 'astronomy', 'observing', 'Combining light from separated telescopes to reach the resolution of a telescope as wide as their separation.', 'The Event Horizon Telescope imaged a black hole this way, linking radio telescopes across the Earth.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('light-pollution', 'Light pollution', 'astronomy', 'observing', 'Artificial light that brightens the night sky and hides faint objects.', 'Light pollution is measured on the Bortle scale, from 1 (pristine dark sky) to 9 (inner-city sky).', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('celestial-sphere', 'Celestial sphere', 'astronomy', 'celestial', 'An imaginary sphere on which stars appear to lie, used as a reference for sky coordinates.', 'The celestial sphere is a model, not a physical object. Its poles and equator are projections of Earth''s own.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('right-ascension', 'Right ascension', 'astronomy', 'celestial', 'Celestial longitude, measured eastward from the vernal equinox, usually in hours, minutes, and seconds.', 'Right ascension and declination together fix a star''s position independent of the observer''s location and time.', 'α', 'h m s', ARRAY['RA']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('declination', 'Declination', 'astronomy', 'celestial', 'Celestial latitude, measured north or south of the celestial equator in degrees.', 'Objects at the celestial north pole have declination +90°. Declination determines whether a star is visible from a given latitude.', 'δ', '°', ARRAY['Dec']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('celestial-equator', 'Celestial equator', 'astronomy', 'celestial', 'The projection of Earth''s equator onto the celestial sphere. It is zero declination.', 'It is tilted against the ecliptic by the obliquity of the ecliptic, about 23.4°.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('ecliptic', 'Ecliptic', 'astronomy', 'celestial', 'The apparent yearly path of the Sun across the celestial sphere.', 'The planets lie close to the ecliptic because the solar system is nearly flat. The zodiac constellations lie along it.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('vernal-equinox', 'Vernal equinox', 'astronomy', 'celestial', 'The point where the ecliptic crosses the celestial equator moving north. It is zero right ascension.', 'The equinox slowly moves westward over about 26,000 years, a motion called precession.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('altitude-and-azimuth', 'Altitude and azimuth', 'astronomy', 'celestial', 'Horizon coordinates: altitude above the horizon, and azimuth measured along the horizon from north.', 'Altitude and azimuth change with time and observer location. Telescope mounts are often driven in these coordinates.', NULL, '°', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('sidereal-day', 'Sidereal day', 'astronomy', 'celestial', 'The time for Earth to rotate once relative to the distant stars: about 23 h 56 min 4 s.', 'The solar day is about four minutes longer, because Earth also moves along its orbit each day.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('vector', 'Vector', 'stem', 'mathematics', 'A quantity with both magnitude and direction, such as velocity or force.', 'Vectors add by components and are drawn as arrows. Their components depend on the chosen coordinate frame.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('scalar', 'Scalar', 'stem', 'mathematics', 'A quantity with magnitude only, such as mass, time, or temperature.', 'Scalars combine by ordinary arithmetic. Speed is a scalar; velocity is the corresponding vector.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('derivative', 'Derivative', 'stem', 'mathematics', 'The instantaneous rate of change of one quantity with respect to another. It is the slope of a curve.', 'Velocity is the derivative of position with respect to time, and acceleration is the derivative of velocity.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('integral', 'Integral', 'stem', 'mathematics', 'The accumulation of a quantity. A definite integral gives the area under a curve between two limits.', 'Integration reverses differentiation. Distance travelled is the integral of speed over time.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('differential-equation', 'Differential equation', 'stem', 'mathematics', 'An equation relating a function to its derivatives. It governs motion, heat flow, and orbits.', 'Newton''s second law applied to a body is a differential equation. Solving it gives the body''s trajectory.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('eigenvalue', 'Eigenvalue', 'stem', 'mathematics', 'A scalar λ such that A·v = λv for some non-zero vector v. Used in stability and vibration analysis.', 'The eigenvalues of a system matrix show whether a system is stable and at what frequencies it vibrates.', 'λ', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('logarithm', 'Logarithm', 'stem', 'mathematics', 'The exponent to which a base must be raised to give a number. Used for scales such as magnitude and decibels.', 'log(ab) = log a + log b. Logarithmic scales compress very large ranges, as in the stellar magnitude scale.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('least-squares', 'Least squares', 'stem', 'mathematics', 'A method of fitting a model by minimising the sum of squared differences between data and model.', 'Least squares is the standard way to fit orbits, calibrate instruments, and estimate parameters from noisy measurements.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('standard-deviation', 'Standard deviation', 'stem', 'mathematics', 'A measure of how spread out data are around the mean.', 'Written σ. For a normal distribution, about 68% of values lie within one standard deviation of the mean.', 'σ', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('taylor-series', 'Taylor series', 'stem', 'mathematics', 'An expansion of a function as an infinite sum of its derivatives at one point.', 'Truncating a Taylor series gives approximations that engineers use for small angles, small velocities, and linearised models.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('newton-s-second-law', 'Newton''s second law', 'stem', 'physics', 'The net force on a body equals its mass times its acceleration: F = ma.', 'The law applies in the inertial frame. Rocket and aircraft equations of motion are built from it.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('newton-s-third-law', 'Newton''s third law', 'stem', 'physics', 'Every action has an equal and opposite reaction. The basis of rocket propulsion.', 'A rocket pushes exhaust backward, and the exhaust pushes the rocket forward. Wings push air down, and the air pushes the wing up.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('conservation-of-momentum', 'Conservation of momentum', 'stem', 'physics', 'In a closed system the total momentum remains constant.', 'Momentum conservation explains rocket thrust, collisions, and the recoil of a gun.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('conservation-of-energy', 'Conservation of energy', 'stem', 'physics', 'Energy cannot be created or destroyed, only converted from one form to another.', 'Orbital energy, kinetic plus gravitational potential, stays constant on a Keplerian orbit.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('kinetic-energy', 'Kinetic energy', 'stem', 'physics', 'Energy of motion: KE = ½mv².', 'Kinetic energy grows with the square of speed, so doubling speed quadruples it.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('potential-energy', 'Potential energy', 'stem', 'physics', 'Stored energy due to position in a force field. Gravitational potential energy is −GMm/r.', 'Potential energy is defined only up to a constant. Orbital mechanics takes it as zero at infinity.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('work', 'Work', 'stem', 'physics', 'Force applied through a distance: W = F·d·cos θ.', 'Work is a scalar. Only the component of force along the displacement does work.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('power', 'Power', 'stem', 'physics', 'The rate at which work is done or energy is transferred: P = W/t.', 'Power is measured in watts. Aircraft and rocket engines are rated by power or thrust.', NULL, 'W', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('torque', 'Torque', 'stem', 'physics', 'The turning effect of a force about a point: τ = r × F.', 'Torque sets how fast a body spins up. Control surfaces create torque about an aircraft''s centre of gravity.', 'τ', 'N·m', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('angular-momentum', 'Angular momentum', 'stem', 'physics', 'Rotational momentum, L = Iω. It is conserved when no external torque acts.', 'Angular momentum conservation explains why a spinning skater speeds up when pulling in their arms, and why a satellite''s orbit keeps its shape.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('centripetal-acceleration', 'Centripetal acceleration', 'stem', 'physics', 'Acceleration toward the centre of a circular path: a = v²/r.', 'Centripetal acceleration is provided by a real force, such as gravity for a satellite or lift for a banked turn.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('universal-gravitation', 'Universal gravitation', 'stem', 'physics', 'The attractive force between two masses: F = Gm₁m₂/r², with G ≈ 6.674 × 10⁻¹¹ N·m²/kg².', 'Newton''s law of gravitation. The orbital period of a satellite follows from it, and from centripetal acceleration.', 'G', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('doppler-effect', 'Doppler effect', 'stem', 'physics', 'The change in observed frequency or wavelength when a source and observer move relative to each other.', 'The Doppler effect measures the radial velocity of stars, the speed of approaching or receding vehicles, and the radar speed of aircraft.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('electromagnetic-spectrum', 'Electromagnetic spectrum', 'stem', 'physics', 'The full range of electromagnetic radiation, from radio waves to gamma rays. All travel at the speed of light in vacuum.', 'Astronomers observe the sky across the spectrum. Some wavelengths, such as X-rays and most infrared, are blocked by the atmosphere and need space telescopes.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('black-body-radiation', 'Black-body radiation', 'stem', 'physics', 'Thermal radiation from an ideal absorber whose spectrum depends only on its temperature.', 'Wien''s displacement law gives the peak wavelength from temperature. Stars and the cosmic microwave background are close to black bodies.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('stefan-boltzmann-law', 'Stefan–Boltzmann law', 'stem', 'physics', 'The total power radiated per unit area by a black body is σT⁴.', 'σ is the Stefan–Boltzmann constant, about 5.67 × 10⁻⁸ W/(m²·K⁴). Temperature enters to the fourth power.', 'σ', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('inverse-square-law', 'Inverse-square law', 'stem', 'physics', 'The intensity of radiation or gravity falls with the square of distance.', 'Doubling the distance from a light source cuts its brightness to one quarter. Gravity and radiation both obey it.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('first-law-of-thermodynamics', 'First law of thermodynamics', 'stem', 'physics', 'Energy is conserved: ΔU = Q − W.', 'The change in internal energy equals heat added minus work done by the system. Engine cycles are analysed with it.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('entropy', 'Entropy', 'stem', 'physics', 'A measure of disorder. In an isolated system it never decreases.', 'The second law of thermodynamics limits the efficiency of every heat engine and sets the direction of natural processes.', 'S', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('ideal-gas-law', 'Ideal gas law', 'stem', 'physics', 'PV = nRT, relating pressure, volume, amount of gas, and temperature.', 'Real gases approach this law at low pressure and high temperature. It sets the standard atmosphere model used in aviation.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('reynolds-number', 'Reynolds number', 'stem', 'physics', 'The ratio of inertial to viscous forces in a flow. It determines whether the flow is laminar or turbulent.', 'Re = ρvL/μ. Wind tunnel tests are scaled by matching Reynolds number to the full-size aircraft.', 'Re', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('density', 'Density', 'stem', 'physics', 'Mass per unit volume: ρ = m/V.', 'Air density falls with altitude, which lowers lift, engine power, and propeller efficiency.', 'ρ', 'kg/m³', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('pressure', 'Pressure', 'stem', 'physics', 'Force per unit area. Standard sea-level atmospheric pressure is 101,325 Pa.', 'Pressure drops with height. Pilots set altimeters to a reference pressure to read altitude.', 'p', 'Pa', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('resonance', 'Resonance', 'stem', 'physics', 'A system driven at its natural frequency responds with a large amplitude.', 'Resonance can be useful, as in tuned circuits, or dangerous, as when a structure or engine vibrates at a natural frequency.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('simple-harmonic-motion', 'Simple harmonic motion', 'stem', 'physics', 'Oscillation in which the restoring force is proportional to displacement.', 'A mass on a spring and a small pendulum both follow simple harmonic motion. Its period does not depend on amplitude for small swings.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('stress', 'Stress', 'stem', 'engineering', 'Force per unit area in a material: σ = F/A.', 'Normal stress acts perpendicular to a surface; shear stress acts parallel to it.', 'σ', 'Pa', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('strain', 'Strain', 'stem', 'engineering', 'Relative deformation: the change in length divided by the original length.', 'Strain is dimensionless. Elastic strain disappears when the load is removed; plastic strain does not.', 'ε', NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('young-s-modulus', 'Young''s modulus', 'stem', 'engineering', 'The ratio of stress to strain in the elastic range. It measures stiffness.', 'Aluminium alloys have a Young''s modulus of about 70 GPa, and carbon fibre composites are stiffer along the fibre direction.', 'E', 'Pa', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('factor-of-safety', 'Factor of safety', 'stem', 'engineering', 'The ratio of failure load to working load: a deliberate design margin.', 'Aircraft structures are designed to ultimate loads of about 1.5 times limit loads, which is a common factor of safety.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('fatigue', 'Fatigue', 'stem', 'engineering', 'Cracking and failure caused by repeated loading, even at stresses below the static strength.', 'Fatigue is a leading cause of structural failure in aircraft. Inspection intervals are set to find cracks before they grow to critical size.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('finite-element-analysis', 'Finite element analysis', 'stem', 'engineering', 'A numerical method that divides a structure into small elements to predict stress and deformation.', 'FEA is used for wings, rocket structures, heat shields, and most other load-bearing parts. Results are only as good as the model and boundary conditions.', NULL, NULL, ARRAY['FEA']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('computational-fluid-dynamics', 'Computational fluid dynamics', 'stem', 'engineering', 'Numerical simulation of fluid flow by solving the governing equations on a grid or mesh.', 'CFD complements wind tunnel testing. It predicts lift, drag, heating, and mixing in engines.', NULL, NULL, ARRAY['CFD']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('systems-engineering', 'Systems engineering', 'stem', 'engineering', 'The discipline of defining requirements, designing, integrating, and verifying complex systems.', 'Systems engineering links the requirements of the mission to the design of each subsystem and tracks them through testing.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('verification-and-validation', 'Verification and validation', 'stem', 'engineering', 'Verification checks that the design meets its specification. Validation checks that it meets the user''s real need.', 'A design can pass verification and still fail validation if the specification itself was wrong.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('failure-modes-and-effects-analysis', 'Failure modes and effects analysis', 'stem', 'engineering', 'A systematic review of how each component can fail, and what the consequences would be.', 'FMEA ranks failure modes by severity, occurrence, and detectability to decide where to add design margin or redundancy.', NULL, NULL, ARRAY['FMEA']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('trade-study', 'Trade study', 'stem', 'engineering', 'A structured comparison of design options against weighted criteria.', 'Trade studies make design choices traceable. They record why one option was chosen over another.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('feedback-control', 'Feedback control', 'stem', 'engineering', 'Using a measured output to adjust the input and reduce the error from a desired value.', 'Autopilots, engine governors, and attitude control systems are all feedback controllers.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('pid-controller', 'PID controller', 'stem', 'engineering', 'A controller that combines proportional, integral, and derivative terms of the error.', 'The proportional term reacts to the present error, the integral term removes steady offset, and the derivative term anticipates change.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('signal-to-noise-ratio', 'Signal-to-noise ratio', 'stem', 'engineering', 'The ratio of signal power to noise power, usually expressed in decibels.', 'Radio links, sensors, and telescope detectors are all limited by their signal-to-noise ratio.', NULL, 'dB', ARRAY['SNR']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('stall-speed', 'Stall speed', 'aviation', 'aviation', 'The minimum speed at which the wing stalls in a given configuration.', 'Stall speed rises with weight and load factor, and falls with flaps extended. Pilots fly above it with a margin.', 'Vs', 'kt', ARRAY['Vs']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('centre-of-gravity', 'Centre of gravity', 'aviation', 'aviation', 'The point through which an aircraft''s weight acts. It must stay within published limits for safe flight.', 'A forward CG improves stability but needs more elevator force; an aft CG reduces stability and can make recovery from a stall impossible.', NULL, NULL, ARRAY['CG']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('pitot-static-system', 'Pitot-static system', 'aviation', 'aviation', 'Measures total and static pressure to give airspeed, altitude, and vertical speed.', 'Blockage of the pitot tube or static port gives false airspeed or altitude readings.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('international-standard-atmosphere', 'International Standard Atmosphere', 'aviation', 'aviation', 'A reference atmosphere: 15 °C and 1013.25 hPa at sea level, with temperature falling about 6.5 °C per km.', 'Aircraft performance charts and altimeter settings are referenced to ISA.', NULL, NULL, ARRAY['ISA']::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('load-factor', 'Load factor', 'aviation', 'aviation', 'The ratio of lift to weight in a manoeuvre. It is 1 g in level unaccelerated flight.', 'In a steep turn the load factor rises, and so does the stall speed. Structural limits are expressed as maximum load factors.', NULL, 'g', '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
insert into public.academy_terms (id, term, track, category, short, detail, symbol, units, aka) values ('adverse-yaw', 'Adverse yaw', 'aviation', 'aviation', 'Yaw in the opposite direction to a roll, caused by the drag of the raised aileron.', 'Frise ailerons and differential aileron deflection reduce adverse yaw. Rudder input counters it.', NULL, NULL, '{}'::text[]) on conflict (id) do update set term = excluded.term, track = excluded.track, category = excluded.category, short = excluded.short, detail = excluded.detail, symbol = excluded.symbol, units = excluded.units, aka = excluded.aka;
